	private const string InstallScriptTemplate = "# HebrewBooks client installer (generated by hbsearch). Shows a WPF install window.\n$ErrorActionPreference = 'Stop'\n$authority   = '__AUTHORITY__'\n$searchHost  = '__SEARCHHOST__'\n$searchPort  = __SEARCHPORT__\n$networkBase = '__NETBASE__'\n$shareUser   = '__SHAREUSER__'\n$sharePass   = '__SHAREPASS__'\n$setupUrlNet = '__SETUPURL_NET__'\n$setupUrlLan = 'http://' + $authority + '/Setup.exe'\n\nAdd-Type -AssemblyName PresentationFramework\n\n$xaml = @'\n<Window xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'\n        xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'\n        Title='התקנת ארון הספרים הדיגיטלי' Height='250' Width='470'\n        WindowStartupLocation='CenterScreen' ResizeMode='NoResize' FlowDirection='RightToLeft'\n        Background='#F3F4F6'>\n  <Grid Margin='26'>\n    <Grid.RowDefinitions>\n      <RowDefinition Height='Auto'/>\n      <RowDefinition Height='*'/>\n      <RowDefinition Height='Auto'/>\n      <RowDefinition Height='Auto'/>\n    </Grid.RowDefinitions>\n    <TextBlock Grid.Row='0' Text='\ud83d\udcda ארון הספרים הדיגיטלי' FontSize='22' FontWeight='Bold' Foreground='#1F2937'/>\n    <TextBlock x:Name='StatusText' Grid.Row='1' Text='מתחיל בהתקנה...' FontSize='15' Foreground='#374151'\n               TextWrapping='Wrap' VerticalAlignment='Center' Margin='0,18'/>\n    <ProgressBar x:Name='Bar' Grid.Row='2' Height='10' IsIndeterminate='True' Foreground='#2563EB'\n                 Background='#E5E7EB' BorderThickness='0'/>\n    <Button x:Name='CloseBtn' Grid.Row='3' Content='סגור' Width='120' Height='36' Margin='0,20,0,0'\n            HorizontalAlignment='Left' Visibility='Collapsed' Background='#2563EB' Foreground='White'\n            BorderThickness='0' FontSize='14'/>\n  </Grid>\n</Window>\n'@\n\n[xml]$xamlXml = $xaml\n$win = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xamlXml))\n$status   = $win.FindName('StatusText')\n$bar      = $win.FindName('Bar')\n$closeBtn = $win.FindName('CloseBtn')\n$closeBtn.Add_Click({ $win.Close() })\n\n$script:state     = 0\n$script:proc      = $null\n$script:setupTmp  = $null\n$script:dlFromNet = $false\n$script:total     = 0      # total bytes of the Setup being downloaded (0 = unknown -> indeterminate bar)\n$script:dlLabel   = ''     # base 'downloading from ...' text; the live percent is appended to it\n\nfunction Finish-Ok {\n    $script:timer.Stop()\n    $bar.IsIndeterminate = $false\n    $bar.Value = 100\n    $status.Text = 'ההתקנה הושלמה! אפשר להפעיל את ארון הספרים הדיגיטלי.'\n    $closeBtn.Visibility = 'Visible'\n}\nfunction Finish-Err($m) {\n    $script:timer.Stop()\n    $bar.IsIndeterminate = $false\n    $bar.Foreground = '#DC2626'\n    $status.Text = 'שגיאה: ' + $m\n    $closeBtn.Visibility = 'Visible'\n}\nfunction Start-Download($url) {\n    # Download via a child PowerShell + Invoke-WebRequest — curl.exe is NOT present on every station\n    # (its absence raised 'cannot find the file' and broke even the LAN fallback). The child sets\n    # ProgressPreference=SilentlyContinue (IWR -OutFile is very slow otherwise) and exits 1 on any web\n    # error so state 4 falls back to the LAN server. Polled via -PassThru so the window stays responsive.\n    $cmd = '$ProgressPreference=''SilentlyContinue''; try { Invoke-WebRequest -Uri ''' + $url + ''' -OutFile ''' + $script:setupTmp + ''' -UseBasicParsing } catch { exit 1 }'\n    $script:proc = Start-Process -FilePath 'powershell.exe' -PassThru -WindowStyle Hidden -ArgumentList @('-NoProfile','-Command',$cmd)\n}\n\n$script:timer = New-Object System.Windows.Threading.DispatcherTimer\n$script:timer.Interval = [TimeSpan]::FromMilliseconds(300)\n$script:timer.Add_Tick({\n  try {\n    switch ($script:state) {\n      0 {\n        # Write the server connection BEFORE installing, so an auto-launch of the app reads it.\n        $status.Text = 'מגדיר את החיבור לשרת...'\n        $cfgDir  = Join-Path $env:APPDATA 'HebrewBooks'\n        New-Item -ItemType Directory -Force -Path $cfgDir | Out-Null\n        $cfgPath = Join-Path $cfgDir 'settings.json'\n        if (Test-Path $cfgPath) { $cfg = Get-Content $cfgPath -Raw -Encoding UTF8 | ConvertFrom-Json } else { $cfg = [pscustomobject]@{} }\n        if (-not $cfg.Paths) { $cfg | Add-Member -NotePropertyName 'Paths' -NotePropertyValue ([pscustomobject]@{}) -Force }\n        # Master switch (root level) — without it every Effective* path getter returns null and the host/UNC below are ignored.\n        $cfg | Add-Member -NotePropertyName 'NetworkInstall' -NotePropertyValue $true -Force\n        $cfg.Paths | Add-Member -NotePropertyName 'SearchServiceHost' -NotePropertyValue $searchHost -Force\n        $cfg.Paths | Add-Member -NotePropertyName 'SearchServicePort' -NotePropertyValue ([int]$searchPort) -Force\n        if ($networkBase) {\n          # The shared base on the server holds Books / indexes / Otzraya / Personal AND the master\n          # Katalog.db. Stations read those from the share (derived from NetworkBasePath) but must NOT\n          # open the catalog directly off the SMB share: a WAL SQLite file over SMB throws 'database is\n          # locked' / 'disk I/O error' under cross-station contention and crashed catalog load. So the\n          # DATA ROOT is LOCAL — CatalogSync copies the master down to it on every launch and the app\n          # reads a fast, writable LOCAL catalog. (Earlier builds set the data root = the UNC share,\n          # which is what caused the crashes.) Per-user LocalAppData needs no admin and keeps the big\n          # catalog out of the roaming profile.\n          $localRoot = Join-Path $env:LOCALAPPDATA 'HebrewBooks\\Data'\n          New-Item -ItemType Directory -Force -Path $localRoot | Out-Null\n          $cfg.Paths | Add-Member -NotePropertyName 'NetworkBasePath' -NotePropertyValue $networkBase -Force\n          $cfg.Paths | Add-Member -NotePropertyName 'LastDataRootPath' -NotePropertyValue $localRoot -Force\n          # Clear any remembered volume serial from a prior (UNC-rooted) install so DataRootResolver\n          # doesn't lock onto the wrong volume — it re-finds the LOCAL root via LastDataRootPath.\n          $cfg.Paths | Add-Member -NotePropertyName 'DataVolumeSerial' -NotePropertyValue 0 -Force\n        }\n        ($cfg | ConvertTo-Json -Depth 30) | Set-Content -Path $cfgPath -Encoding UTF8\n        $script:state = 1\n      }\n      1 {\n        # Auto-connect to the SMB share (read-only account) so the user never types share creds.\n        # Best-effort: a hiccup here (e.g. already connected with other creds) must NOT fail the install.\n        if ($shareUser -and $networkBase) {\n          $status.Text = 'מתחבר לתיקייה המשותפת בשרת...'\n          try {\n            $shareRoot = $networkBase\n            if ($networkBase -match '^(\\\\\\\\[^\\\\]+\\\\[^\\\\]+)') { $shareRoot = $matches[1] }\n            & cmdkey /add:$searchHost /user:$shareUser /pass:$sharePass | Out-Null\n            & net use $shareRoot /user:$shareUser $sharePass /persistent:yes 2>$null | Out-Null\n          } catch {}\n        }\n        $script:state = 2\n      }\n      2 {\n        # Internet-first probe — a child PowerShell HEAD request against the GitHub release Setup, with\n        # its own short timeout. (A ranged GET failed: GitHub doesn't forward Range through the CDN\n        # redirect; HEAD follows the redirect and returns 200.) Non-blocking — state 3 polls it.\n        $status.Text = 'בודק חיבור לאינטרנט...'\n        $script:setupTmp = Join-Path $env:TEMP ('HebrewBooks-Setup-' + [guid]::NewGuid().ToString('N') + '.exe')\n        $pcmd = '$ProgressPreference=''SilentlyContinue''; try { Invoke-WebRequest -Uri ''' + $setupUrlNet + ''' -Method Head -TimeoutSec 8 -UseBasicParsing | Out-Null } catch { exit 1 }'\n        $script:proc = Start-Process -FilePath 'powershell.exe' -PassThru -WindowStyle Hidden -ArgumentList @('-NoProfile','-Command',$pcmd)\n        $script:state = 3\n      }\n      3 {\n        # Probe finished → internet reachable (exit 0) downloads from GitHub; otherwise from the LAN server.\n        if ($script:proc.HasExited) {\n          if ($script:proc.ExitCode -eq 0) { $script:dlLabel = 'מוריד את תוכנת ההתקנה מהאינטרנט (מהיר)'; $script:dlFromNet = $true;  $dlUrl = $setupUrlNet }\n          else                             { $script:dlLabel = 'מוריד את תוכנת ההתקנה מהשרת המקומי';     $script:dlFromNet = $false; $dlUrl = $setupUrlLan }\n          $status.Text = $script:dlLabel + '...'\n          # Total size for a REAL percent bar (best-effort). The source is already known-reachable so\n          # this HEAD is quick; if Content-Length is missing the bar simply stays indeterminate.\n          $script:total = 0\n          try { $hr = Invoke-WebRequest -Uri $dlUrl -Method Head -UseBasicParsing -TimeoutSec 10; $cl = $hr.Headers['Content-Length']; if ($cl) { $script:total = [int64]$cl } } catch {}\n          if ($script:total -gt 0) { $bar.IsIndeterminate = $false; $bar.Value = 0 }\n          Start-Download $dlUrl\n          $script:state = 4\n        }\n      }\n      4 {\n        # Live percent from the growing temp file vs the known total (when Content-Length was available).\n        if ($script:total -gt 0 -and (Test-Path $script:setupTmp)) {\n          $pct = [int](100 * (Get-Item $script:setupTmp).Length / $script:total)\n          if ($pct -gt 99) { $pct = 99 }\n          $bar.Value = $pct\n          $status.Text = $script:dlLabel + ' — ' + $pct + '%'\n        }\n        if ($script:proc.HasExited) {\n          $ok = ($script:proc.ExitCode -eq 0) -and (Test-Path $script:setupTmp) -and ((Get-Item $script:setupTmp).Length -gt 100000)\n          if ($ok) {\n            if ($script:total -gt 0) { $bar.Value = 100 }\n            $script:state = 5\n          } elseif ($script:dlFromNet) {\n            # Internet download failed mid-way → fall back to the LAN server, stay in this state.\n            $script:dlFromNet = $false\n            $script:dlLabel = 'מוריד את תוכנת ההתקנה מהשרת המקומי'\n            $status.Text = $script:dlLabel + '...'\n            Remove-Item $script:setupTmp -Force -ErrorAction SilentlyContinue\n            $script:total = 0\n            try { $hr = Invoke-WebRequest -Uri $setupUrlLan -Method Head -UseBasicParsing -TimeoutSec 10; $cl = $hr.Headers['Content-Length']; if ($cl) { $script:total = [int64]$cl } } catch {}\n            Start-Download $setupUrlLan\n          } else {\n            throw 'הורדת תוכנת ההתקנה נכשלה.'\n          }\n        }\n      }\n      5 {\n        $status.Text = 'מתקין את התוכנה...'\n        $script:proc = Start-Process -FilePath $script:setupTmp -PassThru\n        $script:state = 6\n      }\n      6 {\n        if ($script:proc.HasExited) {\n          Remove-Item $script:setupTmp -Force -ErrorAction SilentlyContinue\n          Finish-Ok\n        }\n      }\n    }\n  } catch {\n    Finish-Err $_.Exception.Message\n  }\n})\n$script:timer.Start()\n$win.ShowDialog() | Out-Null\n";

