	private static async Task<int> Main(string[] args)
	{
		Console.OutputEncoding = Encoding.UTF8;
		Options opts;
		try
		{
			opts = Options.Parse(args);
		}
		catch (ArgUsageException ex)
		{
			Console.Error.WriteLine("error: " + ex.Message);
			Console.Error.WriteLine();
			Options.PrintUsage(Console.Error);
			return 1;
		}
		if (opts.ShowHelp)
		{
			Options.PrintUsage(Console.Out);
			return 0;
		}
		if (!opts.Serve && string.IsNullOrWhiteSpace(opts.Query))
		{
			Console.Error.WriteLine("error: no query text given.");
			Console.Error.WriteLine();
			Options.PrintUsage(Console.Error);
			return 1;
		}
		BookshelfOptions options;
		string dataRoot;
		try
		{
			JsonSettingsStore jsonSettingsStore = new JsonSettingsStore();
			options = jsonSettingsStore.Load();
			dataRoot = new DataRootResolver(jsonSettingsStore).Resolve(args);
		}
		catch (DataRootNotFoundException ex2)
		{
			Console.Error.WriteLine("error: " + ex2.Message);
			return 2;
		}
		PathResolver paths = new PathResolver(dataRoot, options);
		Console.Error.WriteLine("data-root: " + paths.DataDriveRoot);
		SqliteConnectionFactory sqliteConnectionFactory = new SqliteConnectionFactory(paths.CatalogDbPath);
		sqliteConnectionFactory.EnsureSchema();
		CatalogRepository catalog = new CatalogRepository(sqliteConnectionFactory);
		DtSearchNetEngine engine = new DtSearchNetEngine(new EngineOptions());
		PopularitySnapshot popularity = new PopularitySnapshot(paths);
		SearchOrchestrator orchestrator = new SearchOrchestrator(engine, catalog, paths, popularity, NullLogger<SearchOrchestrator>.Instance);
		try
		{
			await orchestrator.EnsureIndexOpenAsync();
			return (!opts.Serve) ? (await RunOneShotAsync(opts, paths, engine, orchestrator)) : (await ServeAsync(opts, paths, engine, orchestrator));
		}
		catch (Exception ex3)
		{
			Console.Error.WriteLine("error: " + ex3.Message);
			return 3;
		}
	}

	private static async Task<int> RunOneShotAsync(Options opts, PathResolver paths, DtSearchNetEngine engine, SearchOrchestrator orchestrator)
	{
		string transformed;
		SearchQuery searchQuery = BuildQuery(opts, paths, engine, out transformed);
		if ((object)searchQuery == null)
		{
			Console.Error.WriteLine("error: query reduced to empty after transform.");
			return 1;
		}
		Console.Error.WriteLine("query: " + transformed);
		IReadOnlyList<SearchResultRow> readOnlyList = await orchestrator.RunAsync(searchQuery, opts.Sort);
		IEnumerable<SearchResultRow> source = readOnlyList;
		if (opts.ExcludePersonal)
		{
			source = source.Where((SearchResultRow r) => !string.Equals(r.Book.SourceType, "Personal", StringComparison.Ordinal));
		}
		int? limit = opts.Limit;
		if (limit.HasValue)
		{
			int valueOrDefault = limit.GetValueOrDefault();
			source = source.Take(valueOrDefault);
		}
		List<SearchResultRow> list = source.ToList();
		EmitResults(opts, transformed, readOnlyList.Count, list);
		Console.Error.WriteLine($"matched {readOnlyList.Count} document(s); emitted {list.Count}.");
		return 0;
	}

	private static async Task<int> ServeAsync(Options opts, PathResolver paths, DtSearchNetEngine engine, SearchOrchestrator orchestrator)
	{
		SemaphoreSlim gate = new SemaphoreSlim(1, 1);
		using HttpListener listener = new HttpListener();
		string text = $"http://+:{opts.Port}/";
		listener.Prefixes.Add(text);
		try
		{
			listener.Start();
		}
		catch (HttpListenerException ex)
		{
			Console.Error.WriteLine("failed to listen on " + text + ": " + ex.Message);
			Console.Error.WriteLine($"On Windows the URL must be reserved once (run as admin):\n  netsh http add urlacl url={text} user=Everyone\n…or run this process elevated.");
			return 4;
		}
		Console.Error.WriteLine($"hbsearch serving on {text}  (data-root: {paths.DataDriveRoot})");
		Console.Error.WriteLine("Endpoints: GET /search?q=<query>&...  |  GET /health    (Ctrl+C to stop)");
		if (opts.InstallEnabled)
		{
			string text2 = Path.Combine(AppContext.BaseDirectory, "installer-cache");
			string text3 = Path.Combine(text2, "Setup.exe");
			_servedInstaller = (File.Exists(text3) ? text3 : ((!string.IsNullOrWhiteSpace(opts.InstallerPath) && File.Exists(opts.InstallerPath)) ? opts.InstallerPath : null));
			Console.Error.WriteLine((_servedInstaller == null) ? "Client install ENABLED: GET /install + GET /Setup.exe  (no local installer yet — will download from GitHub when online)" : ("Client install ENABLED: GET /install + GET /Setup.exe  (serving: " + _servedInstaller + ")"));
			if (opts.InstallerUpdate)
			{
				RefreshInstallerAsync(opts, text2, text3);
			}
			else
			{
				Console.Error.WriteLine("  installer auto-update disabled (--no-installer-update): serving local/cached only.");
			}
		}
		if (opts.UpdateFeedEnabled)
		{
			Console.Error.WriteLine($"Client auto-update ENABLED: GET /vpk/*  (LAN Velopack feed for '{opts.UpdateChannel}' stations, mirrored from {opts.InstallerRepo})");
			RefreshVpkFeedAsync(opts);
		}
		while (true)
		{
			HttpListenerContext ctx;
			try
			{
				ctx = await listener.GetContextAsync();
			}
			catch
			{
				break;
			}
			HandleRequestAsync(ctx, opts, paths, engine, orchestrator, gate);
		}
		return 0;
	}

	private static async Task HandleRequestAsync(HttpListenerContext ctx, Options opts, PathResolver paths, DtSearchNetEngine engine, SearchOrchestrator orchestrator, SemaphoreSlim gate)
	{
		HttpListenerResponse resp = ctx.Response;
		try
		{
			resp.Headers["Access-Control-Allow-Origin"] = "*";
			string text = ctx.Request.Url?.AbsolutePath ?? "/";
			if (opts.InstallEnabled && (string.Equals(text, "/", StringComparison.Ordinal) || string.Equals(text, "/index.html", StringComparison.OrdinalIgnoreCase)))
			{
				await HandleLandingPageAsync(ctx, opts, resp);
				return;
			}
			if (string.Equals(text, "/install.bat", StringComparison.OrdinalIgnoreCase) || string.Equals(text, "/install.cmd", StringComparison.OrdinalIgnoreCase))
			{
				await HandleInstallBatAsync(ctx, opts, resp);
				return;
			}
			if (string.Equals(text, "/install", StringComparison.OrdinalIgnoreCase) || string.Equals(text, "/install.ps1", StringComparison.OrdinalIgnoreCase))
			{
				await HandleInstallScriptAsync(ctx, opts, resp);
				return;
			}
			if (string.Equals(text, "/Setup.exe", StringComparison.OrdinalIgnoreCase) || string.Equals(text, "/download/setup", StringComparison.OrdinalIgnoreCase))
			{
				await HandleInstallerDownloadAsync(opts, resp);
				return;
			}
			if (text.StartsWith("/vpk/", StringComparison.OrdinalIgnoreCase))
			{
				await HandleVpkAsync(opts, text, resp);
				return;
			}
			if (string.Equals(text, "/health", StringComparison.OrdinalIgnoreCase))
			{
				await WriteTextAsync(resp, 200, "application/json; charset=utf-8", "{\"ok\":true,\"service\":\"hbsearch\"}");
				return;
			}
			if (string.Equals(text, "/inbook", StringComparison.OrdinalIgnoreCase))
			{
				await HandleInBookAsync(ctx.Request, resp, paths, engine, orchestrator, gate);
				return;
			}
			if (!string.Equals(text, "/search", StringComparison.OrdinalIgnoreCase))
			{
				await WriteTextAsync(resp, 404, "application/json; charset=utf-8", JsonError("unknown route (use /search, /inbook, /health, /install or /Setup.exe)"));
				return;
			}
			Options ro;
			IReadOnlyList<string> restrictFileIds;
			try
			{
				(ro, restrictFileIds) = await ParseRequestAsync(ctx.Request);
			}
			catch (ArgUsageException ex)
			{
				await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError(ex.Message));
				return;
			}
			catch (JsonException ex2)
			{
				await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError("bad JSON body: " + ex2.Message));
				return;
			}
			if (string.IsNullOrWhiteSpace(ro.Query))
			{
				await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError("missing 'q'"));
				return;
			}
			await gate.WaitAsync();
			IReadOnlyList<SearchResultRow> readOnlyList2;
			try
			{
				SearchQuery searchQuery;
				try
				{
					searchQuery = BuildQuery(ro, paths, engine, out string _, restrictFileIds);
				}
				catch (Exception ex3)
				{
					await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError(ex3.Message));
					return;
				}
				IReadOnlyList<SearchResultRow> readOnlyList = (((object)searchQuery != null) ? (await orchestrator.RunAsync(searchQuery, ro.Sort)) : Array.Empty<SearchResultRow>());
				readOnlyList2 = readOnlyList;
			}
			finally
			{
				gate.Release();
			}
			IEnumerable<SearchResultRow> enumerable = readOnlyList2;
			if (ro.ExcludePersonal)
			{
				enumerable = enumerable.Where((SearchResultRow r) => !string.Equals(r.Book.SourceType, "Personal", StringComparison.Ordinal));
			}
			int? limit = ro.Limit;
			if (limit.HasValue)
			{
				int valueOrDefault = limit.GetValueOrDefault();
				enumerable = enumerable.Take(valueOrDefault);
			}
			resp.StatusCode = 200;
			resp.SendChunked = true;
			resp.ContentType = "application/x-ndjson; charset=utf-8";
			await using StreamWriter writer = new StreamWriter(resp.OutputStream, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			int n = 0;
			foreach (SearchResultRow item in enumerable)
			{
				await writer.WriteLineAsync(JsonSerializer.Serialize(ToDto(item), JsonOut));
				int num = n + 1;
				n = num;
				if (num % 100 == 0)
				{
					await writer.FlushAsync();
				}
			}
			await writer.FlushAsync();
		}
		catch (Exception ex4)
		{
			try
			{
				Console.Error.WriteLine("request error: " + ex4.Message);
			}
			catch
			{
			}
		}
		finally
		{
			try
			{
				resp.OutputStream.Close();
			}
			catch
			{
			}
		}
	}

	private static async Task HandleInstallerDownloadAsync(Options opts, HttpListenerResponse resp)
	{
		string servedInstaller = _servedInstaller;
		if (!opts.InstallEnabled || string.IsNullOrWhiteSpace(servedInstaller) || !File.Exists(servedInstaller))
		{
			await WriteTextAsync(resp, 404, "application/json; charset=utf-8", JsonError("installer not available yet (no local --installer and no download cached)"));
			return;
		}
		FileInfo fileInfo = new FileInfo(servedInstaller);
		resp.StatusCode = 200;
		resp.ContentType = "application/octet-stream";
		resp.ContentLength64 = fileInfo.Length;
		resp.Headers["Content-Disposition"] = "attachment; filename=Setup.exe";
		await using FileStream fs = File.OpenRead(servedInstaller);
		await fs.CopyToAsync(resp.OutputStream).ConfigureAwait(continueOnCapturedContext: false);
	}

	private static async Task RefreshInstallerAsync(Options opts, string cacheDir, string cachedSetup)
	{
		_ = 6;
		try
		{
			Directory.CreateDirectory(cacheDir);
			string versionFile = Path.Combine(cacheDir, "version.txt");
			string latestTag;
			using (CancellationTokenSource cts = new CancellationTokenSource(TimeSpan.FromSeconds(8.0)))
			{
				using HttpRequestMessage req = new HttpRequestMessage(HttpMethod.Get, "https://api.github.com/repos/" + opts.InstallerRepo + "/releases/latest");
				req.Headers.UserAgent.ParseAdd("hbsearch-installer-updater");
				req.Headers.Accept.ParseAdd("application/vnd.github+json");
				using HttpResponseMessage apiResp = await Http.SendAsync(req, cts.Token).ConfigureAwait(continueOnCapturedContext: false);
				apiResp.EnsureSuccessStatusCode();
				using JsonDocument jsonDocument = JsonDocument.Parse(await apiResp.Content.ReadAsStringAsync(cts.Token).ConfigureAwait(continueOnCapturedContext: false));
				latestTag = (jsonDocument.RootElement.TryGetProperty("tag_name", out var value) ? value.GetString() : null);
			}
			if (string.IsNullOrWhiteSpace(latestTag))
			{
				Console.Error.WriteLine("installer-update: could not read latest release tag; keeping local/cached installer.");
				return;
			}
			string a = ((!File.Exists(versionFile) || !File.Exists(cachedSetup)) ? null : (await File.ReadAllTextAsync(versionFile).ConfigureAwait(continueOnCapturedContext: false)).Trim());
			if (string.Equals(a, latestTag, StringComparison.Ordinal))
			{
				_servedInstaller = cachedSetup;
				Console.Error.WriteLine("installer-update: cached offline Setup is current (" + latestTag + ").");
				return;
			}
			string requestUri = "https://github.com/" + opts.InstallerRepo + "/releases/latest/download/HebrewBooks-offline-Setup.exe";
			Console.Error.WriteLine("installer-update: downloading offline Setup " + latestTag + " ...");
			string tmp = cachedSetup + ".download";
			using (HttpResponseMessage apiResp = await Http.GetAsync(requestUri, HttpCompletionOption.ResponseHeadersRead).ConfigureAwait(continueOnCapturedContext: false))
			{
				apiResp.EnsureSuccessStatusCode();
				await using FileStream fs = new FileStream(tmp, FileMode.Create, FileAccess.Write, FileShare.None);
				await apiResp.Content.CopyToAsync(fs).ConfigureAwait(continueOnCapturedContext: false);
			}
			try
			{
				if (File.Exists(cachedSetup))
				{
					File.Delete(cachedSetup);
				}
			}
			catch
			{
			}
			File.Move(tmp, cachedSetup);
			await File.WriteAllTextAsync(versionFile, latestTag).ConfigureAwait(continueOnCapturedContext: false);
			_servedInstaller = cachedSetup;
			long value2 = new FileInfo(cachedSetup).Length / 1048576;
			Console.Error.WriteLine($"installer-update: now serving offline Setup {latestTag} ({value2} MB).");
		}
		catch (Exception ex)
		{
			Console.Error.WriteLine($"installer-update: skipped ({ex.GetType().Name}: {ex.Message}); serving local/cached installer.");
		}
	}

	private static bool IsSafeVpkName(string name)
	{
		int length = name.Length;
		if (length > 0 && length < 200 && name.All(delegate(char c)
		{
			bool flag = char.IsLetterOrDigit(c);
			if (!flag)
			{
				bool flag2 = ((c == '-' || c == '.' || c == '_') ? true : false);
				flag = flag2;
			}
			return flag;
		}))
		{
			if (!name.EndsWith(".nupkg", StringComparison.OrdinalIgnoreCase))
			{
				if (name.StartsWith("releases.", StringComparison.OrdinalIgnoreCase))
				{
					return name.EndsWith(".json", StringComparison.OrdinalIgnoreCase);
				}
				return false;
			}
			return true;
		}
		return false;
	}

	private static async Task HandleVpkAsync(Options opts, string path, HttpListenerResponse resp)
	{
		if (!opts.UpdateFeedEnabled)
		{
			await WriteTextAsync(resp, 404, "application/json; charset=utf-8", JsonError("update feed not enabled on this server"));
			return;
		}
		string text = Uri.UnescapeDataString(path.Substring("/vpk/".Length));
		if (!IsSafeVpkName(text))
		{
			await WriteTextAsync(resp, 404, "application/json; charset=utf-8", JsonError("unknown update asset"));
			return;
		}
		bool isJson = text.EndsWith(".json", StringComparison.OrdinalIgnoreCase);
		string text2 = await MirrorVpkAssetAsync(opts, text, isJson).ConfigureAwait(continueOnCapturedContext: false);
		if (text2 == null)
		{
			await WriteTextAsync(resp, 502, "application/json; charset=utf-8", JsonError("update asset unavailable (not cached and could not be fetched from the releases repo)"));
		}
		else
		{
			await ServeFileAsync(resp, text2, isJson ? "application/json; charset=utf-8" : "application/octet-stream").ConfigureAwait(continueOnCapturedContext: false);
		}
	}

	private static async Task<string?> MirrorVpkAssetAsync(Options opts, string name, bool forceRefresh)
	{
		string local = Path.Combine(VpkCacheDir, name);
		bool haveCached = File.Exists(local);
		if (haveCached && !forceRefresh)
		{
			return local;
		}
		try
		{
			Directory.CreateDirectory(VpkCacheDir);
			string requestUri = "https://github.com/" + opts.InstallerRepo + "/releases/latest/download/" + name;
			string tmp = local + ".download";
			using (HttpResponseMessage dl = await Http.GetAsync(requestUri, HttpCompletionOption.ResponseHeadersRead).ConfigureAwait(continueOnCapturedContext: false))
			{
				dl.EnsureSuccessStatusCode();
				await using FileStream fs = new FileStream(tmp, FileMode.Create, FileAccess.Write, FileShare.None);
				await dl.Content.CopyToAsync(fs).ConfigureAwait(continueOnCapturedContext: false);
			}
			try
			{
				if (File.Exists(local))
				{
					File.Delete(local);
				}
			}
			catch
			{
			}
			File.Move(tmp, local);
			return local;
		}
		catch (Exception ex)
		{
			if (!haveCached)
			{
				Console.Error.WriteLine($"vpk-feed: could not fetch {name} ({ex.GetType().Name}: {ex.Message}).");
			}
			return haveCached ? local : null;
		}
	}

	private static async Task RefreshVpkFeedAsync(Options opts)
	{
		_ = 2;
		try
		{
			string name = "releases." + opts.UpdateChannel + ".json";
			string text = await MirrorVpkAssetAsync(opts, name, forceRefresh: true).ConfigureAwait(continueOnCapturedContext: false);
			if (text == null)
			{
				Console.Error.WriteLine("vpk-feed: '" + opts.UpdateChannel + "' feed not available yet (offline or not published); will serve lazily on demand.");
				return;
			}
			using JsonDocument doc = JsonDocument.Parse(await File.ReadAllTextAsync(text).ConfigureAwait(continueOnCapturedContext: false));
			if (!TryGetPropertyCI(doc.RootElement, "assets", out var value) || value.ValueKind != JsonValueKind.Array)
			{
				return;
			}
			int warmed = 0;
			int total = 0;
			foreach (JsonElement item in value.EnumerateArray())
			{
				JsonElement value2;
				string text2 = (TryGetPropertyCI(item, "fileName", out value2) ? value2.GetString() : null);
				if (!string.IsNullOrWhiteSpace(text2) && text2.EndsWith(".nupkg", StringComparison.OrdinalIgnoreCase) && IsSafeVpkName(text2))
				{
					total++;
					if (!File.Exists(Path.Combine(VpkCacheDir, text2)) && await MirrorVpkAssetAsync(opts, text2, forceRefresh: false).ConfigureAwait(continueOnCapturedContext: false) != null)
					{
						warmed++;
					}
				}
			}
			Console.Error.WriteLine($"vpk-feed: '{opts.UpdateChannel}' ready ({total} package(s); {warmed} newly cached).");
		}
		catch (Exception ex)
		{
			Console.Error.WriteLine($"vpk-feed: pre-warm skipped ({ex.GetType().Name}: {ex.Message}); serving lazily on demand.");
		}
	}

	private static bool TryGetPropertyCI(JsonElement el, string name, out JsonElement value)
	{
		if (el.ValueKind == JsonValueKind.Object)
		{
			foreach (JsonProperty item in el.EnumerateObject())
			{
				if (string.Equals(item.Name, name, StringComparison.OrdinalIgnoreCase))
				{
					value = item.Value;
					return true;
				}
			}
		}
		value = default(JsonElement);
		return false;
	}

	private static async Task ServeFileAsync(HttpListenerResponse resp, string file, string contentType)
	{
		FileInfo fileInfo = new FileInfo(file);
		resp.StatusCode = 200;
		resp.ContentType = contentType;
		resp.ContentLength64 = fileInfo.Length;
		await using FileStream fs = File.OpenRead(file);
		await fs.CopyToAsync(resp.OutputStream).ConfigureAwait(continueOnCapturedContext: false);
	}

