	private static async Task HandleInstallBatAsync(HttpListenerContext ctx, Options opts, HttpListenerResponse resp)
	{
		if (!opts.InstallEnabled)
		{
			await WriteTextAsync(resp, 404, "text/plain; charset=utf-8", "install is not enabled on this server");
			return;
		}
		string newValue = ResolveAuthority(ctx, opts);
		string body = "@echo off\nstart \"HebrewBooks\" /min powershell -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -Command \"iex(irm 'http://__AUTHORITY__/install')\"\nexit\n".Replace("__AUTHORITY__", newValue).Replace("\r\n", "\n").Replace("\n", "\r\n");
		resp.Headers["Content-Disposition"] = "attachment; filename=Install-HebrewBooks.bat";
		await WriteTextAsync(resp, 200, "application/octet-stream", body);
	}

	private static async Task HandleInBookAsync(HttpListenerRequest req, HttpListenerResponse resp, PathResolver paths, DtSearchNetEngine engine, SearchOrchestrator orchestrator, SemaphoreSlim gate)
	{
		if (!string.Equals(req.HttpMethod, "POST", StringComparison.OrdinalIgnoreCase))
		{
			await WriteTextAsync(resp, 405, "application/json; charset=utf-8", JsonError("use POST /inbook"));
			return;
		}
		InBookRequest body;
		try
		{
			using StreamReader reader = new StreamReader(req.InputStream, req.ContentEncoding ?? Encoding.UTF8);
			body = JsonSerializer.Deserialize<InBookRequest>(await reader.ReadToEndAsync().ConfigureAwait(continueOnCapturedContext: false), JsonIn) ?? new InBookRequest();
		}
		catch (JsonException ex)
		{
			await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError("bad JSON body: " + ex.Message));
			return;
		}
		if (string.IsNullOrWhiteSpace(body.FileName) || string.IsNullOrWhiteSpace(body.Q))
		{
			await WriteTextAsync(resp, 400, "application/json; charset=utf-8", JsonError("fileName and q are required"));
			return;
		}
		HebAramMap aramMap = (body.Aramaic ? new HebAramMap(() => HebAramMap.ReadFileText(paths.HebAramPath)) : null);
		await gate.WaitAsync();
		InBookHitInfo inBookHitInfo2;
		try
		{
			int? proximity = body.Proximity;
			int defaultProximity;
			if (proximity.HasValue)
			{
				int valueOrDefault = proximity.GetValueOrDefault();
				if (valueOrDefault > 0)
				{
					defaultProximity = valueOrDefault;
					goto IL_03d5;
				}
			}
			defaultProximity = 30;
			goto IL_03d5;
			IL_03d5:
			QueryBuildOptions options = new QueryBuildOptions(AddPrefixLetters: body.Hybur, FirstWordOnly: false, LastWordOnly: false, RasheyTevot: body.Rashetevot ? RasheyTevotMap.LoadFromFile(paths.RasheyTevotPath) : null, ExpandRoots: body.Roots, ExpandNumberGender: body.NumberGender, ExpandGematria: body.Gematria, ExpandSpelling: body.Spelling, Aramaic: aramMap, IndexWordFilter: engine.FilterIndexedWords, MaxTotalExpansions: 200, RequireWordOrder: body.RequireWordOrder, DefaultProximity: defaultProximity, ExpandRashiOcr: body.RashiOcr);
			string text = QueryBuilder.Build(body.Q, options);
			string displayQuery = (string.IsNullOrWhiteSpace(body.DisplayQuery) ? body.Q : body.DisplayQuery);
			InBookHitInfo inBookHitInfo = ((!string.IsNullOrWhiteSpace(text)) ? (await orchestrator.GetInBookHitsCachedAsync(body.FileName, text, displayQuery, body.Hybur, body.Roots, body.NumberGender, body.Gematria, body.Spelling, aramMap, Math.Clamp(body.Fuzziness, 0, 10)).ConfigureAwait(continueOnCapturedContext: false)) : new InBookHitInfo(0, Array.Empty<int>(), Array.Empty<string>()));
			inBookHitInfo2 = inBookHitInfo;
		}
		finally
		{
			gate.Release();
		}
		var value = new
		{
			hitCount = inBookHitInfo2.HitCount,
			pages = inBookHitInfo2.Pages,
			matchedTerms = inBookHitInfo2.MatchedTerms,
			highlightXml = inBookHitInfo2.HighlightXml
		};
		await WriteTextAsync(resp, 200, "application/json; charset=utf-8", JsonSerializer.Serialize(value, JsonOut));
	}

	private static Options OptionsFromQuery(NameValueCollection qs)
	{
		List<string> args = new List<string>();
		string text = qs["q"] ?? qs["query"];
		if (!string.IsNullOrWhiteSpace(text))
		{
			args.Add(text);
		}
		Flag("hybur", "--hybur");
		Flag("roots", "--roots");
		Flag("gematria", "--gematria");
		Flag("spelling", "--spelling");
		Flag("number-gender", "--number-gender");
		Flag("aramaic", "--aramaic");
		Flag("rashetevot", "--rashetevot");
		Flag("first-word", "--first-word");
		Flag("last-word", "--last-word");
		Flag("require-word-order", "--require-word-order");
		Flag("rashi-ocr", "--rashi-ocr");
		Flag("exclude-personal", "--exclude-personal");
		Val("proximity", "--proximity");
		Val("fuzziness", "--fuzziness");
		Val("max", "--max");
		Val("limit", "--limit");
		Val("sort", "--sort");
		Val("corpus", "--corpus");
		return Options.Parse(args.ToArray());
		void Flag(string param, string flag)
		{
			string text2 = qs[param];
			if (text2 != null && (text2.Length == 0 || text2 == "1" || text2.Equals("true", StringComparison.OrdinalIgnoreCase)))
			{
				args.Add(flag);
			}
		}
		void Val(string param, string flag)
		{
			string text2 = qs[param];
			if (!string.IsNullOrEmpty(text2))
			{
				args.Add(flag);
				args.Add(text2);
			}
		}
	}

	private static async Task<(Options opts, IReadOnlyList<string>? restrictFileIds)> ParseRequestAsync(HttpListenerRequest req)
	{
		if (!string.Equals(req.HttpMethod, "POST", StringComparison.OrdinalIgnoreCase))
		{
			return (opts: OptionsFromQuery(req.QueryString), restrictFileIds: null);
		}
		using StreamReader reader = new StreamReader(req.InputStream, req.ContentEncoding ?? Encoding.UTF8);
		SearchRequest searchRequest = JsonSerializer.Deserialize<SearchRequest>(await reader.ReadToEndAsync().ConfigureAwait(continueOnCapturedContext: false), JsonIn) ?? new SearchRequest();
		List<string> args = new List<string>();
		if (!string.IsNullOrWhiteSpace(searchRequest.Q))
		{
			args.Add(searchRequest.Q);
		}
		Flag(searchRequest.Hybur, "--hybur");
		Flag(searchRequest.Roots, "--roots");
		Flag(searchRequest.Gematria, "--gematria");
		Flag(searchRequest.Spelling, "--spelling");
		Flag(searchRequest.NumberGender, "--number-gender");
		Flag(searchRequest.Aramaic, "--aramaic");
		Flag(searchRequest.Rashetevot, "--rashetevot");
		Flag(searchRequest.FirstWord, "--first-word");
		Flag(searchRequest.LastWord, "--last-word");
		Flag(searchRequest.RequireWordOrder, "--require-word-order");
		Flag(searchRequest.RashiOcr, "--rashi-ocr");
		Flag(searchRequest.ExcludePersonal, "--exclude-personal");
		Val(searchRequest.Proximity, "--proximity");
		Val(searchRequest.Fuzziness, "--fuzziness");
		Val(searchRequest.Max, "--max");
		Val(searchRequest.Limit, "--limit");
		if (!string.IsNullOrEmpty(searchRequest.Sort))
		{
			args.Add("--sort");
			args.Add(searchRequest.Sort);
		}
		string[] corpus = searchRequest.Corpus;
		if (corpus != null && corpus.Length > 0)
		{
			args.Add("--corpus");
			args.Add(string.Join(',', searchRequest.Corpus));
		}
		corpus = searchRequest.RestrictFileIds;
		string[] item = ((corpus != null && corpus.Length > 0) ? searchRequest.RestrictFileIds : null);
		return (opts: Options.Parse(args.ToArray()), restrictFileIds: item);
		void Flag(bool on, string f)
		{
			if (on)
			{
				args.Add(f);
			}
		}
		void Val(int? v, string f)
		{
			if (v.HasValue)
			{
				int valueOrDefault = v.GetValueOrDefault();
				args.Add(f);
				args.Add(valueOrDefault.ToString(CultureInfo.InvariantCulture));
			}
		}
	}

	private static async Task WriteTextAsync(HttpListenerResponse resp, int status, string contentType, string body)
	{
		resp.StatusCode = status;
		resp.ContentType = contentType;
		byte[] bytes = Encoding.UTF8.GetBytes(body);
		resp.ContentLength64 = bytes.Length;
		await resp.OutputStream.WriteAsync(bytes);
	}

	private static string JsonError(string msg)
	{
		return JsonSerializer.Serialize(new
		{
			ok = false,
			error = msg
		}, JsonOut);
	}

	private static SearchQuery? BuildQuery(Options opts, PathResolver paths, DtSearchNetEngine engine, out string transformed, IReadOnlyList<string>? restrictFileIds = null)
	{
		transformed = "";
		QueryBuildOptions options = new QueryBuildOptions(opts.Proximity, opts.Hybur, opts.FirstWord, opts.LastWord, opts.RasheyTevot ? RasheyTevotMap.LoadFromFile(paths.RasheyTevotPath) : null, opts.Roots, opts.NumberGender, opts.Gematria, opts.Spelling, opts.Aramaic ? new HebAramMap(() => HebAramMap.ReadFileText(paths.HebAramPath)) : null, engine.FilterIndexedWords, 200, RequireWordOrder: opts.RequireWordOrder, ExpandRashiOcr: opts.RashiOcr, ExpandWeakLetters: opts.WeakLetters);
		string text = QueryBuilder.Build(opts.Query, options);
		if (string.IsNullOrWhiteSpace(text))
		{
			return null;
		}
		transformed = text;
		IReadOnlyList<string> restrictToIndexPaths = null;
		if (opts.Corpora.Count > 0)
		{
			List<string> list = new List<string>();
			if (opts.Corpora.Contains("PDF"))
			{
				list.Add(paths.IndexesRoot);
			}
			if (opts.Corpora.Contains("Text"))
			{
				list.Add(paths.OtzrayaIndexPath);
			}
			if (opts.Corpora.Contains("Personal"))
			{
				list.Add(paths.PersonalIndexPath);
			}
			if (list.Count > 0)
			{
				restrictToIndexPaths = list;
			}
		}
		return new SearchQuery(transformed, opts.Proximity, opts.Hybur, IncludeNumbers: true, opts.MaxFiles, opts.Fuzziness, restrictFileIds, restrictToIndexPaths, QueryBuilder.CountMatchWords(opts.Query));
	}

	private static object ToDto(SearchResultRow r)
	{
		return new
		{
			fileId = r.Book.FileID,
			bookName = r.Book.BookName,
			authorName = r.Book.AuthorName,
			printPlace = r.Book.PrintPlace,
			printYear = r.Book.PrintYear,
			countPage = r.Book.CountPage,
			categories = r.Book.Categories,
			sourceType = r.Book.SourceType,
			relativePath = r.Book.RelativePath,
			hitCount = r.HitCount,
			firstHitPage = r.PageNumber
		};
	}

	private static void EmitResults(Options opts, string transformed, int total, List<SearchResultRow> rows)
	{
		if (opts.Format == OutputFormat.Jsonl)
		{
			foreach (SearchResultRow row in rows)
			{
				Console.Out.WriteLine(JsonSerializer.Serialize(ToDto(row), JsonOut));
			}
			return;
		}
		string value = JsonSerializer.Serialize(new
		{
			query = opts.Query,
			transformedQuery = transformed,
			totalMatched = total,
			returned = rows.Count,
			results = rows.Select(ToDto).ToList()
		}, new JsonSerializerOptions(JsonOut)
		{
			WriteIndented = opts.Pretty
		});
		Console.Out.WriteLine(value);
	}
}
